bg = importlib.util.module_from_spec(spec); spec.loader.exec_module(bg)
norm = bg.norm
dry = '--dry' in sys.argv
cache = {}
def lines_of(path):
    if path not in cache:
        cache[path] = (repo/path).read_text(encoding='utf-8', errors='replace').split('\n')
    return cache[path]
def near_ok(path, ln, quote):
    lines = lines_of(path)
    window = norm("\n".join(re.sub(r"^\s*>\s?", "", x) for x in lines[max(0, ln-4): ln+3]))
    head = norm(re.sub(r"^\s*>\s?", "", quote))[:50]
    return head in window
changed, vanished = 0, []
