cd /tmp/claude-0/-home-user-guidebook/db856d85-2082-5d35-9529-aa996506261b/scratchpad/rehearsals/A2-phase1 && S=/tmp/claude-0/-home-user-guidebook/db856d85-2082-5d35-9529-aa996506261b/scratchpad && cat > "$S/rehearsals/A2-phase1_tools/rm_registry_prose.py" <<'PY'
"""Delete note / floor_basis / reason / prior_note scalar fields over 300 chars from check-registry.yaml by TEXT edit.
Never loads/dumps; uses yaml.compose only to locate line spans. Prints per-key (count, lines)."""
import yaml, sys
path = 'governance/check-registry.yaml'
KEYS = {'note', 'floor_basis', 'reason', 'prior_note'}
lines = open(path, encoding='utf-8').read().split('\n')
spans = []
def walk(n):
    if isinstance(n, yaml.MappingNode):
        for k, v in n.value:
            if k.value in KEYS and isinstance(v, yaml.ScalarNode) and len(v.value) > 300:
                s = k.start_mark.line
                e = v.end_mark.line if v.end_mark.column > 0 else v.end_mark.line - 1
                spans.append((k.value, s, e))
            walk(v)
    elif isinstance(n, yaml.SequenceNode):
        for v in n.value: walk(v)
walk(yaml.compose(open(path, encoding='utf-8')))
spans.sort(key=lambda x: x[1])
for a, b in zip(spans, spans[1:]): assert a[2] < b[1], (a, b)
stat = {}
for k, s, e in spans:
    c = stat.setdefault(k, [0, 0]); c[0] += 1; c[1] += e - s + 1
drop = set()
for k, s, e in spans: drop.update(range(s, e + 1))
out = [l for i, l in enumerate(lines) if i not in drop]
open(path, 'w', encoding='utf-8').write('\n'.join(out))
print({k: tuple(v) for k, v in stat.items()}, 'lines removed', len(lines) - len(out))
PY
